<div class="right_col" role="main"><h2>Generate Admission Test Seat Plan</h2><div class="card shadow-sm"><div class="card-body"><?= form_open('school/admission/seat-plans/generate') ?><div class="row"><div class="col-md-6 mb-3"><label>Admission test *</label><select id="test-id" class="form-control" name="test_id" required><?php foreach($tests as $t): ?><option value="<?= $t->id ?>" data-school="<?= $t->school_id ?>"><?= esc($t->title) ?></option><?php endforeach ?></select></div><div class="col-md-6 mb-3"><label>Plan title *</label><input class="form-control" name="title" value="<?= esc(old('title','Admission Test Seat Plan')) ?>" required></div><div class="col-md-6 mb-3"><label>Allocation method</label><select class="form-control" name="allocation_method"><option value="sequential">Sequential by application number</option><option value="random">Seeded random order</option></select></div><div class="col-md-6 mb-3"><label>Seat number format</label><select class="form-control" name="seat_number_format"><option value="numeric">Numeric</option><option value="alpha_numeric">Alpha numeric</option></select></div><div class="col-12"><label>Rooms *</label><div class="row" id="room-list"><?php foreach($rooms as $r): ?><div class="col-md-4 mb-2 room-option" data-school="<?= $r->school_id ?>"><label class="border rounded p-2 d-block"><input type="checkbox" name="rooms[]" value="<?= $r->id ?>"> <?= esc($r->room_name) ?> (<?= esc($r->room_no) ?>) — <?= $r->capacity ?> seats</label></div><?php endforeach ?></div></div></div><button class="btn btn-primary mt-3">Generate seat plan</button><?= form_close() ?></div></div></div><script>function filterRooms(){const o=document.getElementById('test-id').selectedOptions[0],school=o?o.dataset.school:'';document.querySelectorAll('.room-option').forEach(x=>{x.style.display=x.dataset.school===school?'block':'none';if(x.dataset.school!==school)x.querySelector('input').checked=false;});}document.getElementById('test-id').addEventListener('change',filterRooms);filterRooms();</script>
